import { Component, OnInit } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';

interface LicnaKarta {
  id: number;
  ime: string;
  prezime: string;
  jmbg: string;
  datumIzdavanja: string;
  datumVazenja: string;
  grad: string;
  drzava: string;
  status: string;
}

@Component({
  selector: 'app-licna',
  templateUrl: './licna.component.html',
  styleUrls: ['./licna.component.css']
})
export class LicnaComponent implements OnInit {

  zahtevi: LicnaKarta[] = [];
  token: string = ''; // ovde stavi JWT token koji čuvaš pri login-u

  constructor(private http: HttpClient) { }

  ngOnInit(): void {
    this.ucitajZahteve();
  }

  ucitajZahteve() {
    const headers = new HttpHeaders().set('Authorization', `Bearer ${this.token}`);
    this.http.get<LicnaKarta[]>('http://localhost:8080/licna-karta/svi-zahtevi', { headers })
      .subscribe({
        next: (data) => this.zahtevi = data,
        error: (err) => console.error(err)
      });
  }

  podnesiZahtev() {
    // ovde možeš otvoriti modal ili redirect ka formi za podnošenje zahteva
  }

  produziLicnu() {
    // ovde možeš otvoriti modal ili redirect ka produžavanju lične
  }

}
<div class="container mt-5">

  <!-- Dugmici za akcije -->
  <div class="d-flex justify-content-center mb-4">
    <button class="btn btn-primary me-3" >Zahtev za vađenje lične</button>
    <button class="btn btn-secondary" >Zahtev za produžavanje lične</button>
  </div>

  <!-- Tabela sa zahtevima -->
  <div class="table-responsive">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th>
        <th>Ime</th>
        <th>Prezime</th>
        <th>JMBG</th>
        <th>Datum izdavanja</th>
        <th>Važi do</th>
        <th>Status</th>
        <th>Grad</th>
        <th>Država</th>
      </tr>
      </thead>
      <tbody>
      <tr *ngFor="let zahtev of zahtevi; let i = index">
        <td>{{ i + 1 }}</td>
        <td>{{ zahtev.ime }}</td>
        <td>{{ zahtev.prezime }}</td>
        <td>{{ zahtev.jmbg }}</td>
        <td>{{ zahtev.datumIzdavanja | date:'dd.MM.yyyy' }}</td>
        <td>{{ zahtev.datumVazenja | date:'dd.MM.yyyy' }}</td>
        <td>{{ zahtev.status }}</td>
        <td>{{ zahtev.grad }}</td>
        <td>{{ zahtev.drzava }}</td>
      </tr>
      </tbody>
    </table>
  </div>

</div>
